  "inlineSchema": "// Schéma Prisma pour l'application ACS Archive\n// Tous les noms sont en français\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// Énumération des rôles utilisateurs\nenum RoleUtilisateur {\n  ADMIN\n  GESTIONNAIRE\n  EMPLOYE\n  CONSULTANT\n}\n\n// Modèle Utilisateur\nmodel Utilisateur {\n  id                String          @id @default(cuid())\n  nomUtilisateur    String          @unique // Connexion par nom d'utilisateur\n  nom               String\n  prenom            String\n  email             String? // Optionnel\n  motDePasse        String\n  role              RoleUtilisateur @default(EMPLOYE)\n  estActif          Boolean         @default(true)\n  dateCreation      DateTime        @default(now())\n  dateModification  DateTime        @updatedAt\n  derniereConnexion DateTime?\n\n  // Relations\n  documents        Document[]\n  journalActivites JournalActivite[]\n\n  @@map(\"utilisateurs\")\n}\n\n// Modèle Catégorie de documents\n// Structure adaptée à l'archivage ACS\n// CLIENT → EXERCICE (Année) → RISQUE → TYPE COURRIER → DOCUMENTS\n\nmodel Client {\n  id           String     @id @default(cuid())\n  nom          String     @unique\n  numeroClient String?    @unique\n  type         TypeClient @default(ENTREPRISE)\n  email        String?\n  telephone    String?\n  adresse      String?\n  exercices    Exercice[]\n  creeLe       DateTime   @default(now())\n  modifieLe    DateTime   @updatedAt\n\n  @@map(\"clients\")\n}\n\nenum TypeClient {\n  ENTREPRISE\n  PARTICULIER\n}\n\nmodel Exercice {\n  id        String         @id @default(cuid())\n  annee     Int\n  clientId  String\n  client    Client         @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  risques   Risque[]\n  statut    StatutExercice @default(ACTIF)\n  creeLe    DateTime       @default(now())\n  modifieLe DateTime       @updatedAt\n\n  @@unique([clientId, annee])\n  @@map(\"exercices\")\n}\n\nenum StatutExercice {\n  ACTIF\n  ARCHIVE\n  CLOTURE\n}\n\nmodel Risque {\n  id           String     @id @default(cuid())\n  type         TypeRisque\n  numeroPolice String?\n  exerciceId   String\n  exercice     Exercice   @relation(fields: [exerciceId], references: [id], onDelete: Cascade)\n  documents    Document[]\n  creeLe       DateTime   @default(now())\n  modifieLe    DateTime   @updatedAt\n\n  @@map(\"risques\")\n}\n\nenum TypeRisque {\n  AUTOMOBILE\n  SANTE\n  HABITATION\n  VIE\n  RESPONSABILITE_CIVILE\n  AUTRE\n}\n\nmodel Document {\n  id               String            @id @default(cuid())\n  titre            String\n  description      String?\n  cheminFichier    String\n  typeFichier      String\n  tailleFichier    Int\n  typeCourrier     TypeCourrier\n  risqueId         String\n  risque           Risque            @relation(fields: [risqueId], references: [id], onDelete: Cascade)\n  auteurId         String\n  auteur           Utilisateur       @relation(fields: [auteurId], references: [id])\n  categorieId      String?\n  categorie        Categorie?        @relation(fields: [categorieId], references: [id], onDelete: SetNull)\n  dateDocument     DateTime?\n  reference        String?\n  journalActivites JournalActivite[]\n  creeLe           DateTime          @default(now())\n  modifieLe        DateTime          @updatedAt\n  estArchive       Boolean           @default(false) // Archivé automatiquement si ancien\n  dateArchivage    DateTime? // Date d'archivage automatique\n\n  @@index([risqueId])\n  @@index([auteurId])\n  @@index([categorieId])\n  @@index([creeLe])\n  @@map(\"documents\")\n}\n\nmodel Categorie {\n  id          String     @id @default(cuid())\n  nom         String     @unique\n  description String?\n  couleur     String     @default(\"#D32027\")\n  documents   Document[]\n  creeLe      DateTime   @default(now())\n  modifieLe   DateTime   @updatedAt\n\n  @@map(\"categories\")\n}\n\nenum TypeCourrier {\n  ACS_VERS_CLIENT // Courrier ACS → Client\n  ACS_VERS_COMPAGNIE // Courrier ACS → Compagnie\n}\n\n// Énumération des types d'actions\nenum TypeAction {\n  CREATION\n  MODIFICATION\n  SUPPRESSION\n  CONSULTATION\n  TELECHARGEMENT\n  EXPORT\n  ARCHIVAGE_AUTO\n  RESTAURATION\n}\n\n// Modèle Journal d'activité (Audit Trail)\nmodel JournalActivite {\n  id         String     @id @default(cuid())\n  action     TypeAction\n  details    String?\n  adresseIp  String?\n  dateAction DateTime   @default(now())\n\n  // Relations\n  utilisateurId String\n  utilisateur   Utilisateur @relation(fields: [utilisateurId], references: [id])\n  documentId    String?\n  document      Document?   @relation(fields: [documentId], references: [id])\n\n  @@index([utilisateurId])\n  @@index([documentId])\n  @@index([dateAction])\n  @@map(\"journal_activites\")\n}\n",
